"use client";

import * as React from "react";
import { Toggle as TogglePrimitive } from "@base-ui/react/toggle";
import { cva, type VariantProps } from "class-variance-authority";

import { cn } from "@/lib/utils";
import { pressedWash } from "./_shared";

type WithClassName<P> = Omit<P, "className"> & { className?: string };

/**
 * Firefly Toggle: a pill that holds its state. Off, it is quiet: a bare
 * label that warms on hover, or an outlined chip on the white page.
 * Pressed, it takes the pale accent wash behind an olive line. It never
 * glows, because the glow belongs to the one primary action.
 */
const toggleVariants = cva(
  [
    "inline-flex shrink-0 select-none items-center justify-center gap-1.5 whitespace-nowrap rounded-full border border-transparent",
    "font-medium text-foreground",
    "transition-[background-color,border-color,color] duration-fast ease-out",
    "focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-ring",
    "data-[disabled]:pointer-events-none data-[disabled]:cursor-not-allowed data-[disabled]:text-(--foreground-disabled)",
    pressedWash,
    "[&_svg]:pointer-events-none [&_svg]:size-4 [&_svg]:shrink-0",
  ].join(" "),
  {
    variants: {
      variant: {
        default: "bg-transparent hover:not-data-[pressed]:bg-secondary",
        outline:
          "border-(--line-strong) bg-background hover:not-data-[pressed]:bg-muted data-[disabled]:border-border data-[disabled]:bg-secondary",
      },
      size: {
        sm: "h-7 px-2.5 text-xs",
        default: "h-8 px-3 text-sm",
        lg: "h-10 px-4 text-sm",
      },
    },
    defaultVariants: {
      variant: "default",
      size: "default",
    },
  },
);

const Toggle = React.forwardRef<
  HTMLButtonElement,
  WithClassName<TogglePrimitive.Props> & VariantProps<typeof toggleVariants>
>(({ className, variant, size, ...props }, ref) => (
  <TogglePrimitive
    ref={ref}
    data-slot="toggle"
    className={cn(toggleVariants({ variant, size, className }))}
    {...props}
  />
));
Toggle.displayName = "Toggle";

export { Toggle, toggleVariants };
